import { isCommercialFilterBaselineOption } from 'components/Filter/utils/commercialSelectOptions';
import type { Option } from 'models/Filters';

const BEYOND_BEER = 'BEYOND BEER';
const BEYOND_BEER_PORTFOLIOS = new Set(['MEGABRANDS', 'EXPANSION']);

function normalize(value: unknown): string {
  if (typeof value !== 'string') {
    return '';
  }

  return value.trim().toUpperCase();
}

export function isBeyondBeerGrowthLever(value: unknown): boolean {
  return normalize(value) === BEYOND_BEER;
}

export function isCommercialResultsPortfolioAllowedForGrowthLever(
  portfolio: unknown,
  growthLever: unknown,
): boolean {
  if (!isBeyondBeerGrowthLever(growthLever)) {
    return true;
  }

  return BEYOND_BEER_PORTFOLIOS.has(normalize(portfolio));
}

export function filterCommercialResultsPortfolioOptionsForGrowthLever(
  options: Option[],
  growthLever: unknown,
): Option[] {
  if (!isBeyondBeerGrowthLever(growthLever)) {
    return options;
  }

  return options.filter(
    (option) =>
      isCommercialFilterBaselineOption(option) ||
      isCommercialResultsPortfolioAllowedForGrowthLever(
        option.value,
        growthLever,
      ),
  );
}
